cd /work && python3 - <<'PY'
HB=b'\x7f'; EM=b'\x02'
def mk(name, specials):
    lines=[b"flf2a"+HB+b" 1 1 10 -1 1 0 0 0", b"t"]
    order=list(range(32,127))+[196,214,220,228,246,252,223]
    for code in order:
        c=bytes([code]) if code<128 else bytes([code])
        if code in specials: lines.append(specials[code]+EM)
        elif code==32: lines.append(b'..'+EM)
        else:
            if code<128: lines.append(c*2+EM)
            else: lines.append(b'??'+EM)
    open('/work/tf/'+name+'.flf','wb').write(b"\n".join(lines)+b"\n")
